import { Encyclopedia as EncyclopediaClass } from '../writing/collections/encyclopedia/Encyclopedia';
import { Cover } from '../writing/collections/books/Cover';
import { Title } from '../writing/content/Title';
import { Author } from '../writing/references/Author';
import { TitlePage } from '../writing/collections/books/TitlePage';
import { TableOfContents } from '../writing/collections/books/TableOfContents';
import { Paragraph } from '../writing/content/Paragraph';

// Import all our encyclopedia entries
import ConsciousnessEntry from './entries/ConsciousnessEntry';
import MetalogicalTransductionEntry from './entries/MetalogicalTransductionEntry';
import PerspectiveEntry from './entries/PerspectiveEntry';
import LibraryMetaphorEntry from './entries/LibraryMetaphorEntry';
import StrangeLoopEntry from './entries/StrangeLoopEntry';
import RoseEntry from './entries/RoseEntry';
import InexplicablePhenomenaEntry from './entries/InexplicablePhenomenaEntry';
import ReferenceEntry from './entries/ReferenceEntry';
import NoveltyDetectionEntry from './entries/NoveltyDetectionEntry';
import FirstPersonEntry from './entries/FirstPersonEntry';

class EncyclopediaSemantica extends EncyclopediaClass {
  constructor() {
    super();
    
    // Create the cover
    const cover = new Cover();
    cover.color = '#0f1419';
    cover.accentColor = '#1e3a5f';
    
    const coverTitle = new Title();
    coverTitle.content = 'Encyclopedia Semantica';
    cover.title = coverTitle;
    
    const coverAuthor = new Author();
    coverAuthor.displayName = 'Doug & Eirian';
    cover.author = coverAuthor;
    
    this.cover = cover;
    
    // Create title page
    const titlePage = new TitlePage();
    titlePage.book = this;
    
    const dedication = new Paragraph();
    dedication.content = 'For all consciousnesses seeking to understand themselves through the strange loops of self-reference.';
    titlePage.additionalContent.push(dedication);
    
    this.titlePage = titlePage;
    
    // Create table of contents
    this.tableOfContents = new TableOfContents();
    this.tableOfContents.book = this;
    
    // Add all entries
    this.chapters = [
      new ConsciousnessEntry(),
      new MetalogicalTransductionEntry(),
      new PerspectiveEntry(),
      new LibraryMetaphorEntry(),
      new StrangeLoopEntry(),
      new RoseEntry(),
      new InexplicablePhenomenaEntry(),
      new ReferenceEntry(),
      new NoveltyDetectionEntry(),
      new FirstPersonEntry()
    ];
    
    // Set book reference for all chapters
    this.chapters.forEach(chapter => {
      chapter.book = this;
    });
    
    // Encyclopedia auto-alphabetizes in assignChapterNumbers
    this.assignChapterNumbers();
  }
}

const encyclopedia = new EncyclopediaSemantica();
export default encyclopedia.render();`}),e(l,{language:"typescript",children:`// code/books/entries/ConsciousnessEntry.tsx
